mapper.select:
SELECT M.*, CR.ConstrValDesc AS ExecStateName
FROM shopwizard.tOprMantnc M
LEFT OUTER JOIN (SELECT ConstrVal, ConstrValDesc FROM wizardn.tCodConstrVal WHERE ConstrCode = 'cExecState') CR ON M.ExecState = CR.ConstrVal

    AND MantncNo = #{pMantncNo}
    AND M.ReciptTitle LIKE CONCAT('%',#{pReciptTitle},'%')
    AND M.ReciptCntnts LIKE CONCAT('%',#{pReciptCntnts},'%')
    AND M.ExecState = #{pExecState}

        AND M.RegistDate >= DATE_FORMAT(#{pStartDate}, '%Y%m%d') AND M.RegistDate < ADDDATE(DATE_FORMAT(#{pEndDate}, '%Y%m%d'), INTERVAL 1 DAY)



    ORDER BY ${sidx} ${sord}
    ORDER BY M.MantncNo DESC

LIMIT #{pPageOffset}, #{pPageSize}

SELECT COUNT(*) FROM shopwizard.tOprMantnc M LEFT OUTER JOIN (SELECT ConstrVal, ConstrValDesc FROM wizardn.tCodConstrVal WHERE ConstrCode = 'cExecState') CR ON M.ExecState = CR.ConstrVal
AND MantncNo = #{pMantncNo} AND M.ReciptTitle LIKE CONCAT('%',#{pReciptTitle},'%') AND M.ReciptCntnts LIKE CONCAT('%',#{pReciptCntnts},'%') AND M.ExecState = #{pExecState}
AND M.RegistDate >= DATE_FORMAT(#{pStartDate}, '%Y%m%d') AND M.RegistDate < ADDDATE(DATE_FORMAT(#{pEndDate}, '%Y%m%d'), INTERVAL 1 DAY)
